import React, { useState } from 'react';
import InputMask from 'react-input-mask';
import './App.css';

function App() {
  const [nomeCompleto, setNomeCompleto] = useState('');
  const [dataNascimento, setDataNascimento] = useState('');
  const [telefone, setTelefone] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();

    // Limpar os campos do formulário
    setNomeCompleto('');
    setDataNascimento('');
    setTelefone('');
  };

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Cadastro</h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col">
            <label htmlFor="nomeCompleto" className="mb-1 font-medium text-gray-700">Nome Completo:</label>
            <input
              type="text"
              id="nomeCompleto"
              value={nomeCompleto}
              onChange={(e) => setNomeCompleto(e.target.value)}
              required
              className="p-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
            />
          </div>

          <div className="flex flex-col">
            <label htmlFor="dataNascimento" className="mb-1 font-medium text-gray-700">Data de Nascimento:</label>
            <InputMask
              mask="99/99/9999"
              value={dataNascimento}
              onChange={(e) => setDataNascimento(e.target.value)}
            >
              {(inputProps) => (
                <input
                  {...inputProps}
                  type="text"
                  required
                  className="p-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
                />
              )}
            </InputMask>
          </div>

          <div className="flex flex-col">
            <label htmlFor="telefone" className="mb-1 font-medium text-gray-700">Telefone:</label>
            <InputMask
              mask="(99) 99999-9999"
              value={telefone}
              onChange={(e) => setTelefone(e.target.value)}
            >
              {(inputProps) => (
                <input
                  {...inputProps}
                  type="text"
                  required
                  className="p-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
                />
              )}
            </InputMask>
          </div>

          <button
            type="submit"
            className="w-full py-2 px-4 bg-blue-500 text-white font-semibold rounded-lg hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            Adicionar
          </button>
        </form>
      </div>
    </div>
  );
}

export default App;
